function local(ms){return new Date(ms+Number($('tr-timezone').value)*60000).toISOString().slice(0,19);}
function endAfter(start,years){const d=new Date(start),day=d.getUTCDate();d.setUTCDate(1);d.setUTCFullYear(d.getUTCFullYear()+years);d.setUTCDate(Math.min(day,new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return +d;}
function setForwardDates(){const data=KPTransit.currentPeriods(),start=Date.now(),home=KPHomeDasha.getData(),lastRoot=home.levels[0].rows.at(-1),limit=Math.min(lastRoot.endMs-Number(home.timeZoneHours)*3600000,Date.UTC(2101,0,1)-1),value=$('tr-auto-horizon')?.value||'13',end=Math.min(value==='MD'?Date.parse(data.periods.MD.endUTC):endAfter(start,Number(value)),limit);$('tr-date-range-source').value='custom';$('tr-search-date-start').value=local(start);$('tr-search-date-end').value=local(end);}
function current(){KPTransitSelection.sync(true);for(const [id,value]of [['tr-dba-selection-source','auto-forward'],['tr-period','PD'],['tr-dasha-source','auto'],['tr-direction','all']])if($(id))$(id).value=value;setForwardDates();KPTransitSelection.sync(true);KPTransit.refresh();if($('tr-date-dba-selection'))$('tr-date-dba-selection').open=true;return KPTransit.currentPeriods();}
function sunTracks(data){return KPTransitEventChains.sunTracks(Object.fromEntries(['MD','AD','PD'].map(k=>[k,data.periods[k].id])),currentKPModel,last?.ruling,last?.rulingModel).tracks;}
function draw(){const tbody=$('tr-result-rows');tbody.replaceChildren();for(const row of results){const tr=document.createElement('tr');tr.dataset.track=row.trackId;tr.dataset.entry=row.start;tr.dataset.exit=row.end;for(const value of [row.planet,row.label,row.start,row.end]){const td=document.createElement('td');td.textContent=value;tr.append(td);}tbody.append(tr);}if(!results.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent=text('No matching intervals in the event-supported DBA windows.','घटनेला अनुकूल DBA कालावधीत जुळणारे गोचर नाही.');tr.append(td);tbody.append(tr);}}
